INSERT INTO litigation.rulings(ruling_id,motion_id,date_filed,opinion_url,dispositive_excerpt,decisions_outcome,jev_outcome,heuristic_outcome,decisions_claim_type,jev_claim_type,outcome_final,outcome_final_source,is_magistrate_rr,review_note,label_status,decisions_run_id,jev_run_id,labeled_at) VALUES ('g05-r1','g05-m1','2022-01-19','https://www.govinfo.gov/app/details/USCOURTS-tnmd-3_20-cv-00859/USCOURTS-tnmd-3_20-cv-00859-0','MEMORANDUM OPINION AND ORDER: Plaintiff James Cayton brings this conditionally certified collective action on behalf of himself and others similarly situated under the Fair Labor Standards Act of 1938 (FLSA), 29 U.S.C. §§ 201219. (Doc. No. 1.) Cayton alleges claims against Defendant the Metropolitan Government of Nashville and Davidson County, by the through the Electric Power Board, doing business as Nashville Electric Service (Nashville Electric Service). (Id.) Cayton and fifty-seven opt-in plaintiffs (collectively, Plaintiffs) have filed a motion for leave to file an amended collective and class action complaint. (Doc. No. 59.) Nashville Electric Service has moved for leave to file a sur-reply (Doc. No. 75), which Plaintiffs oppose (Doc. No. 76). Nashville Electric Service''s motion for leave to file a sur-reply (Doc. No. 75) is GRANTED IN PART and DENIED IN PART. Plaintiffs'' motion for leave to file an amended complaint (Doc. No. 59) is GRANTED. The Clerk of Court is DIRECTED to file Plaintiffs'' proposed amended collective and class action complaint (Doc. No. 59-1) as a separate docket entry. Signed by Magistrate Judge Alistair Newbern on 1/19/2022. (DOCKET TEXT SUMMARY ONLY-ATTORNEYS MUST OPEN THE PDF AND READ THE ORDER.)(mg)','not_reached','not_reached',NULL,'flsa','flsa',NULL,NULL,false,'Docket summary does not state the outcome; unconfirmed.','review','2026-10-11-b2-govinfo-decisions','2026-10-11-b2-govinfo-jev','2026-10-11T16:50:00-04:00') ON CONFLICT DO NOTHING;
